// ============================================
// FETCH ALL MARKET DATA - MarketPulse v7.0
// Value Investor Edition
// IPv4 Fix + Buffett Indicator + CAPE + Yield Curve
// ============================================

const dns = require('dns');
dns.setDefaultResultOrder('ipv4first');

const FRED_API_KEY = 'YOUR_FRED_API_KEY_HERE';

const results = {
  // Fear & Greed
  fearGreedValue: 'N/A',
  fearGreedClassification: 'Unknown',
  fearGreedChange1d: 'N/A',
  fearGreedChange1w: 'N/A',
  // Value Investor Dashboard
  buffettIndicator: 'N/A',
  buffettStatus: 'N/A',
  buffettEmoji: '',
  shillerPE: 'N/A',
  shillerStatus: 'N/A',
  shillerEmoji: '',
  yieldCurve: 'N/A',
  yieldCurveStatus: 'N/A',
  yieldCurveEmoji: '',
  sp500VsMa200: 'N/A',
  sp500VsMa200Status: 'N/A',
  sp500VsMa200Emoji: '',
  maSignal: 'N/A',
  // Market Screener
  sp500: 'N/A', sp500Change: 'N/A',
  dowJones: 'N/A', dowJonesChange: 'N/A',
  vix: 'N/A', vixChange: 'N/A',
  gold: 'N/A', goldChange: 'N/A',
  oil: 'N/A', oilChange: 'N/A',
  dxy: 'N/A', dxyChange: 'N/A',
  btc: 'N/A', btcChange: 'N/A',
  // Economic Indicators
  gdpValue: 'N/A', gdpYear: 'N/A',
  cpiValue: 'N/A', cpiYear: 'N/A',
  unemploymentValue: 'N/A', unemploymentYear: 'N/A',
  fedRateValue: 'N/A',
  treasury10Y: 'N/A',
  treasury2Y: 'N/A',
  // Headlines
  headlines: 'No headlines available'
};

function formatDate(dateStr) {
  if (!dateStr) return 'N/A';
  const d = new Date(dateStr);
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  return months[d.getMonth()] + ' ' + d.getFullYear();
}

// ---- 1. CNN FEAR & GREED INDEX ----
try {
  const fgData = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://production.dataviz.cnn.io/index/fearandgreed/graphdata',
    headers: {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
      'Referer': 'https://www.cnn.com/markets/fear-and-greed',
      'Accept': 'application/json'
    },
    timeout: 30000
  });
  if (fgData && fgData.fear_and_greed) {
    const fg = fgData.fear_and_greed;
    results.fearGreedValue = Math.round(fg.score);
    results.fearGreedClassification = fg.rating ?
      fg.rating.charAt(0).toUpperCase() + fg.rating.slice(1) : 'Unknown';
    if (fg.previous_close !== null && fg.previous_close !== undefined) {
      const d = Math.round(fg.score - fg.previous_close);
      results.fearGreedChange1d = (d >= 0 ? '+' : '') + d;
    }
    if (fg.previous_1_week !== null && fg.previous_1_week !== undefined) {
      const w = Math.round(fg.score - fg.previous_1_week);
      results.fearGreedChange1w = (w >= 0 ? '+' : '') + w;
    }
  }
} catch (e) { console.log('Fear & Greed error: ' + e.message); }

// ---- 2. MARKET INDICES, GOLD, OIL, DXY, BTC (Yahoo Finance) ----
const indices = [
  { symbol: '^GSPC', namePrice: 'sp500', nameChange: 'sp500Change', label: 'S&P 500' },
  { symbol: '^DJI', namePrice: 'dowJones', nameChange: 'dowJonesChange', label: 'Dow Jones' },
  { symbol: '^VIX', namePrice: 'vix', nameChange: 'vixChange', label: 'VIX' },
  { symbol: 'GC=F', namePrice: 'gold', nameChange: 'goldChange', label: 'Gold', prefix: '$' },
  { symbol: 'CL=F', namePrice: 'oil', nameChange: 'oilChange', label: 'Oil (WTI)', prefix: '$' },
  { symbol: 'DX-Y.NYB', namePrice: 'dxy', nameChange: 'dxyChange', label: 'US Dollar (DXY)' },
  { symbol: 'BTC-USD', namePrice: 'btc', nameChange: 'btcChange', label: 'Bitcoin', prefix: '$' }
];

let sp500Price = 0;
let sp500Closes = [];

for (const idx of indices) {
  try {
    const range = (idx.symbol === '^GSPC') ? '1y' : '1d';
    const data = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://query1.finance.yahoo.com/v8/finance/chart/' + encodeURIComponent(idx.symbol) + '?interval=1d&range=' + range,
      headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36' },
      timeout: 15000
    });
    if (data && data.chart && data.chart.result && data.chart.result[0]) {
      const result = data.chart.result[0];
      const meta = result.meta;
      const price = meta.regularMarketPrice;
      const prevClose = meta.chartPreviousClose || meta.previousClose;
      if (price) {
        const prefix = idx.prefix || '';
        if (idx.symbol === 'BTC-USD') {
          results[idx.namePrice] = prefix + price.toLocaleString('en-US', {maximumFractionDigits: 0});
        } else {
          results[idx.namePrice] = prefix + price.toFixed(2);
        }
        if (prevClose && prevClose > 0) {
          const changePct = ((price - prevClose) / prevClose) * 100;
          const sign = changePct >= 0 ? '+' : '';
          results[idx.nameChange] = sign + changePct.toFixed(2) + '%';
        }
      }
      // Save S&P 500 data for 200-day MA calculation
      if (idx.symbol === '^GSPC') {
        sp500Price = price;
        const closes = result.indicators.quote[0].close;
        sp500Closes = closes.filter(c => c !== null && c !== undefined);
      }
    }
    await new Promise(r => setTimeout(r, 500));
  } catch (e) { console.log(idx.label + ' error: ' + e.message); }
}

// ---- 3. S&P 500 vs 200-DAY MOVING AVERAGE ----
try {
  if (sp500Closes.length >= 200 && sp500Price > 0) {
    const ma200 = sp500Closes.slice(-200).reduce((a, b) => a + b, 0) / 200;
    const ma50 = sp500Closes.slice(-50).reduce((a, b) => a + b, 0) / Math.min(50, sp500Closes.slice(-50).length);
    const pctVsMa200 = ((sp500Price - ma200) / ma200) * 100;
    results.sp500VsMa200 = (pctVsMa200 >= 0 ? '+' : '') + pctVsMa200.toFixed(1) + '%';
    results.maSignal = ma50 > ma200 ? 'Golden Cross' : 'Death Cross';
    // Color coding
    if (pctVsMa200 > 5) { results.sp500VsMa200Status = 'Strong Bullish'; results.sp500VsMa200Emoji = '🟢🟢'; }
    else if (pctVsMa200 > 0) { results.sp500VsMa200Status = 'Bullish'; results.sp500VsMa200Emoji = '🟢'; }
    else if (pctVsMa200 > -5) { results.sp500VsMa200Status = 'Caution'; results.sp500VsMa200Emoji = '🟡'; }
    else { results.sp500VsMa200Status = 'Bearish Signal'; results.sp500VsMa200Emoji = '🔴'; }
  }
} catch (e) { console.log('MA200 error: ' + e.message); }

// ---- 4. SHILLER PE (CAPE) RATIO ----
try {
  const capeResp = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://www.multpl.com/shiller-pe',
    headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36' },
    timeout: 15000,
    json: false
  });
  if (capeResp && typeof capeResp === 'string') {
    const match = capeResp.match(/Current Shiller PE Ratio[^0-9]*(\d+\.\d+)/);
    if (match) {
      const cape = parseFloat(match[1]);
      results.shillerPE = cape.toFixed(1);
      if (cape < 20) { results.shillerStatus = 'Undervalued'; results.shillerEmoji = '🟢🟢'; }
      else if (cape < 25) { results.shillerStatus = 'Fair Value'; results.shillerEmoji = '🟢'; }
      else if (cape < 30) { results.shillerStatus = 'Slightly Overvalued'; results.shillerEmoji = '🟡'; }
      else if (cape < 35) { results.shillerStatus = 'Overvalued'; results.shillerEmoji = '🟠'; }
      else { results.shillerStatus = 'Strongly Overvalued'; results.shillerEmoji = '🔴'; }
    }
  }
} catch (e) { console.log('CAPE error: ' + e.message); }

// ---- 5. FRED: UNEMPLOYMENT ----
try {
  const unempData = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.stlouisfed.org/fred/series/observations?series_id=UNRATE&api_key=' + FRED_API_KEY + '&file_type=json&limit=1&sort_order=desc',
    timeout: 30000
  });
  if (unempData && unempData.observations && unempData.observations[0]) {
    const obs = unempData.observations[0];
    results.unemploymentValue = obs.value + '%';
    results.unemploymentYear = formatDate(obs.date);
  }
} catch (e) { console.log('FRED Unemployment error: ' + e.message); }

// ---- 6. FRED: CPI INFLATION (YoY) ----
try {
  const cpiData = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.stlouisfed.org/fred/series/observations?series_id=CPIAUCSL&api_key=' + FRED_API_KEY + '&file_type=json&limit=13&sort_order=desc',
    timeout: 30000
  });
  if (cpiData && cpiData.observations && cpiData.observations.length >= 13) {
    const latest = parseFloat(cpiData.observations[0].value);
    const yearAgo = parseFloat(cpiData.observations[12].value);
    const yoyChange = ((latest - yearAgo) / yearAgo) * 100;
    results.cpiValue = yoyChange.toFixed(2) + '%';
    results.cpiYear = formatDate(cpiData.observations[0].date);
  }
} catch (e) { console.log('FRED CPI error: ' + e.message); }

// ---- 7. FRED: GDP GROWTH RATE ----
try {
  const gdpData = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.stlouisfed.org/fred/series/observations?series_id=A191RL1Q225SBEA&api_key=' + FRED_API_KEY + '&file_type=json&limit=1&sort_order=desc',
    timeout: 30000
  });
  if (gdpData && gdpData.observations && gdpData.observations[0]) {
    const obs = gdpData.observations[0];
    const sign = parseFloat(obs.value) >= 0 ? '+' : '';
    results.gdpValue = sign + obs.value + '% (QoQ)';
    results.gdpYear = formatDate(obs.date);
  }
} catch (e) { console.log('FRED GDP error: ' + e.message); }

// ---- 8. FRED: FED FUNDS RATE ----
try {
  const fedData = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.stlouisfed.org/fred/series/observations?series_id=DFEDTARU&api_key=' + FRED_API_KEY + '&file_type=json&limit=10&sort_order=desc',
    timeout: 30000
  });
  if (fedData && fedData.observations) {
    for (let i = 0; i < fedData.observations.length; i++) {
      const val = fedData.observations[i].value;
      if (val && val !== '.' && val !== 'null' && parseFloat(val) > 0) {
        results.fedRateValue = parseFloat(val).toFixed(2) + '%';
        break;
      }
    }
  }
} catch (e) { console.log('FRED Fed Rate error: ' + e.message); }

// ---- 9. FRED: 10-YEAR TREASURY YIELD ----
try {
  const t10Data = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.stlouisfed.org/fred/series/observations?series_id=DGS10&api_key=' + FRED_API_KEY + '&file_type=json&limit=10&sort_order=desc',
    timeout: 30000
  });
  if (t10Data && t10Data.observations) {
    for (let i = 0; i < t10Data.observations.length; i++) {
      const val = t10Data.observations[i].value;
      if (val && val !== '.' && val !== 'null' && parseFloat(val) > 0) {
        results.treasury10Y = parseFloat(val).toFixed(2) + '%';
        break;
      }
    }
  }
} catch (e) { console.log('FRED 10Y error: ' + e.message); }

// ---- 10. FRED: 2-YEAR TREASURY YIELD ----
try {
  const t2Data = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.stlouisfed.org/fred/series/observations?series_id=DGS2&api_key=' + FRED_API_KEY + '&file_type=json&limit=10&sort_order=desc',
    timeout: 30000
  });
  if (t2Data && t2Data.observations) {
    for (let i = 0; i < t2Data.observations.length; i++) {
      const val = t2Data.observations[i].value;
      if (val && val !== '.' && val !== 'null' && parseFloat(val) > 0) {
        results.treasury2Y = parseFloat(val).toFixed(2) + '%';
        break;
      }
    }
  }
} catch (e) { console.log('FRED 2Y error: ' + e.message); }

// ---- 11. YIELD CURVE CALCULATION (10Y - 2Y) ----
try {
  const t10 = parseFloat(results.treasury10Y);
  const t2 = parseFloat(results.treasury2Y);
  if (!isNaN(t10) && !isNaN(t2)) {
    const spread = t10 - t2;
    results.yieldCurve = (spread >= 0 ? '+' : '') + spread.toFixed(2) + '%';
    if (spread < 0) { results.yieldCurveStatus = 'INVERTED (Recession Warning)'; results.yieldCurveEmoji = '🔴'; }
    else if (spread < 0.5) { results.yieldCurveStatus = 'Flat (Caution)'; results.yieldCurveEmoji = '🟡'; }
    else { results.yieldCurveStatus = 'Normal (Healthy)'; results.yieldCurveEmoji = '🟢'; }
  }
} catch (e) { console.log('Yield curve calc error: ' + e.message); }

// ---- 12. BUFFETT INDICATOR (Wilshire 5000 / GDP) ----
try {
  // Fetch Wilshire 5000
  const w5Data = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://query1.finance.yahoo.com/v8/finance/chart/%5EW5000?interval=1d&range=5d',
    headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36' },
    timeout: 15000
  });
  // Fetch GDP from FRED
  const gdpNomData = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.stlouisfed.org/fred/series/observations?series_id=GDP&api_key=' + FRED_API_KEY + '&file_type=json&limit=1&sort_order=desc',
    timeout: 30000
  });
  if (w5Data && w5Data.chart && w5Data.chart.result && w5Data.chart.result[0] &&
      gdpNomData && gdpNomData.observations && gdpNomData.observations[0]) {
    const w5Price = w5Data.chart.result[0].meta.regularMarketPrice;
    // Wilshire 5000: 1 point ~ $1.05 billion (as of 2020)
    const totalMarketCap = w5Price * 1.05; // in billions
    const gdpBillions = parseFloat(gdpNomData.observations[0].value); // GDP in billions
    if (totalMarketCap > 0 && gdpBillions > 0) {
      const ratio = (totalMarketCap / gdpBillions) * 100;
      results.buffettIndicator = ratio.toFixed(0) + '%';
      if (ratio < 100) { results.buffettStatus = 'Undervalued'; results.buffettEmoji = '🟢🟢'; }
      else if (ratio < 120) { results.buffettStatus = 'Fair Value'; results.buffettEmoji = '🟢'; }
      else if (ratio < 150) { results.buffettStatus = 'Slightly Overvalued'; results.buffettEmoji = '🟡'; }
      else if (ratio < 200) { results.buffettStatus = 'Significantly Overvalued'; results.buffettEmoji = '🟠'; }
      else { results.buffettStatus = 'Strongly Overvalued'; results.buffettEmoji = '🔴'; }
    }
  }
} catch (e) { console.log('Buffett Indicator error: ' + e.message); }

// ---- 13. MARKETWATCH RSS HEADLINES ----
try {
  const rssResponse = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://www.marketwatch.com/rss/topstories',
    timeout: 30000,
    json: false
  });
  if (rssResponse && typeof rssResponse === 'string') {
    const titleMatches = rssResponse.match(/<title>([^<]+)<\/title>/g);
    if (titleMatches && titleMatches.length > 1) {
      const titles = [];
      for (let i = 1; i < Math.min(titleMatches.length, 9); i++) {
        let title = titleMatches[i].replace(/<\/?title>/g, '');
        title = title.trim()
          .replace(/&#x201c;/g, '"').replace(/&#x201d;/g, '"')
          .replace(/&#x2019;/g, "'").replace(/&#x2018;/g, "'")
          .replace(/&#x2014;/g, ' - ').replace(/&#x2013;/g, '-')
          .replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#xa0;/g, ' ');
        if (title.length > 10) titles.push(i + '. ' + title);
      }
      if (titles.length > 0) results.headlines = titles.join('\n');
    }
  }
} catch (e) { console.log('RSS error: ' + e.message); }

return [{ json: results }];

// ============================================
// FETCH STOCK PRICES - MarketPulse v7.0
// IPv4 Fix + Retry Logic + Rate Limiting
// ============================================

const dns = require('dns');
dns.setDefaultResultOrder('ipv4first');

const watchlistStr = $input.first().json.watchlist || 'GOOGL,BABA,ADBE';
const symbols = watchlistStr.split(',').map(s => s.trim()).filter(s => s.length > 0);

const stockResults = [];

for (const symbol of symbols) {
  let success = false;
  for (let attempt = 0; attempt < 3 && !success; attempt++) {
    try {
      const data = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://query1.finance.yahoo.com/v8/finance/chart/' + encodeURIComponent(symbol) + '?interval=1d&range=1d',
        headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36' },
        timeout: 15000
      });
      if (data && data.chart && data.chart.result && data.chart.result[0]) {
        const meta = data.chart.result[0].meta;
        const price = meta.regularMarketPrice;
        const prevClose = meta.chartPreviousClose || meta.previousClose;
        if (price) {
          let changePct = 0;
          if (prevClose && prevClose > 0) {
            changePct = ((price - prevClose) / prevClose) * 100;
          }
          const sign = changePct >= 0 ? '+' : '';
          stockResults.push({
            symbol: symbol,
            price: '$' + price.toFixed(2),
            change: sign + changePct.toFixed(2) + '%'
          });
          success = true;
        }
      }
    } catch (e) {
      if (attempt < 2) await new Promise(r => setTimeout(r, 1000 * (attempt + 1)));
    }
    await new Promise(r => setTimeout(r, 500));
  }
  if (!success) {
    stockResults.push({ symbol: symbol, price: 'N/A', change: 'N/A' });
  }
}

let watchlistSummary = '';
if (stockResults.length > 0) {
  watchlistSummary = stockResults.map(s => {
    const arrow = s.change.startsWith('+') ? '  ' : '  ';
    return arrow + s.symbol + ': ' + s.price + ' (' + s.change + ')';
  }).join('\n');
} else {
  watchlistSummary = 'Watchlist data unavailable';
}

return [{ json: { watchlistSummary: watchlistSummary } }];

// ============================================
// COMBINE ALL DATA - MarketPulse v7.0
// Merges market data + stock prices into one
// ============================================

const items = $input.all();
const combined = {};

for (const item of items) {
  const j = item.json || {};
  for (const key of Object.keys(j)) {
    if (j[key] !== undefined && j[key] !== null) {
      combined[key] = j[key];
    }
  }
}

return [{ json: combined }];

// ============================================
// COMPOSE TELEGRAM MESSAGE - MarketPulse v7.0
// Value Investor Edition
// New: Value Investor Dashboard with color indicators
// ============================================

const items = $input.all();
const now = new Date();

let d = {
  fearGreedValue: 'N/A', fearGreedClassification: 'Unknown',
  fearGreedChange1d: 'N/A', fearGreedChange1w: 'N/A',
  buffettIndicator: 'N/A', buffettStatus: 'N/A', buffettEmoji: '',
  shillerPE: 'N/A', shillerStatus: 'N/A', shillerEmoji: '',
  yieldCurve: 'N/A', yieldCurveStatus: 'N/A', yieldCurveEmoji: '',
  sp500VsMa200: 'N/A', sp500VsMa200Status: 'N/A', sp500VsMa200Emoji: '', maSignal: 'N/A',
  sp500: 'N/A', sp500Change: 'N/A',
  dowJones: 'N/A', dowJonesChange: 'N/A',
  vix: 'N/A', vixChange: 'N/A',
  gold: 'N/A', goldChange: 'N/A',
  oil: 'N/A', oilChange: 'N/A',
  dxy: 'N/A', dxyChange: 'N/A',
  btc: 'N/A', btcChange: 'N/A',
  gdpValue: 'N/A', gdpYear: 'N/A',
  cpiValue: 'N/A', cpiYear: 'N/A',
  unemploymentValue: 'N/A', unemploymentYear: 'N/A',
  fedRateValue: 'N/A', treasury10Y: 'N/A', treasury2Y: 'N/A',
  watchlistSummary: 'N/A',
  llmAnalysis: 'Analysis unavailable'
};

for (const item of items) {
  const j = item.json || {};
  for (const key of Object.keys(d)) {
    if (j[key] && j[key] !== 'N/A' && j[key] !== 'Unknown' && j[key] !== 'Analysis unavailable') {
      d[key] = j[key];
    }
  }
  if (j.text && j.text.length > 30) d.llmAnalysis = j.text;
  if (j.response && j.response.length > 30) d.llmAnalysis = j.response;
}

const dateStr = now.toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

// Fear & Greed emoji
const fgScore = parseInt(d.fearGreedValue) || 0;
let fgEmoji = '';
if (fgScore >= 75) fgEmoji = '🟢🟢';
else if (fgScore >= 55) fgEmoji = '🟢';
else if (fgScore >= 45) fgEmoji = '🟡';
else if (fgScore >= 25) fgEmoji = '🟠';
else if (fgScore > 0) fgEmoji = '🔴';

// VIX emoji
const vixVal = parseFloat(d.vix) || 0;
let vixEmoji = '';
if (vixVal >= 30) vixEmoji = '🔴 HIGH';
else if (vixVal >= 20) vixEmoji = '🟠 ELEVATED';
else if (vixVal >= 12) vixEmoji = '🟢 NORMAL';
else if (vixVal > 0) vixEmoji = '🟢🟢 LOW';

function arrow(changeStr) {
  if (!changeStr || changeStr === 'N/A') return '';
  return changeStr.startsWith('+') ? '▲' : '▼';
}

const message = `📊 MarketPulse Daily Digest
━━━━━━━━━━━━━━━━━━━━
📅 ${dateStr}

🏛️ VALUE INVESTOR DASHBOARD

${d.buffettEmoji} BUFFETT INDICATOR: ${d.buffettIndicator}
   Market Cap to GDP | ${d.buffettStatus}

${d.shillerEmoji} SHILLER P/E (CAPE): ${d.shillerPE}
   Cyclically Adjusted P/E | ${d.shillerStatus}

${d.yieldCurveEmoji} YIELD CURVE (10Y-2Y): ${d.yieldCurve}
   Treasury Spread | ${d.yieldCurveStatus}

${d.sp500VsMa200Emoji} S&P 500 vs 200D-MA: ${d.sp500VsMa200}
   Trend Signal | ${d.sp500VsMa200Status} (${d.maSignal})

━━━━━━━━━━━━━━━━━━━━

🎯 FEAR & GREED INDEX ${fgEmoji}
Score: ${d.fearGreedValue}/100 | ${d.fearGreedClassification}
